import { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

interface KeyboardShortcut {
  key: string;
  action: () => void;
  description: string;
  ctrlKey?: boolean;
  altKey?: boolean;
  shiftKey?: boolean;
}

export const useKeyboardShortcuts = () => {
  const navigate = useNavigate();

  const shortcuts: KeyboardShortcut[] = [
    {
      key: 'h',
      action: () => navigate('/'),
      description: 'Go to Home page',
      altKey: true
    },
    {
      key: 'm',
      action: () => navigate('/crypto-market'),
      description: 'Go to Market page',
      altKey: true
    },
    {
      key: 'a',
      action: () => navigate('/ai-tools'),
      description: 'Go to AI Tools page',
      altKey: true
    },
    {
      key: 'l',
      action: () => navigate('/login'),
      description: 'Go to Login page',
      altKey: true
    },
    {
      key: '/',
      action: () => {
        const searchInput = document.querySelector('input[type="search"]') as HTMLInputElement;
        if (searchInput) {
          searchInput.focus();
        }
      },
      description: 'Focus search'
    },
    {
      key: 'Escape',
      action: () => {
        const focusedElement = document.activeElement as HTMLElement;
        if (focusedElement) {
          focusedElement.blur();
        }
      },
      description: 'Clear focus'
    }
  ];

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      const shortcut = shortcuts.find(s => {
        return s.key.toLowerCase() === event.key.toLowerCase() &&
               !!s.ctrlKey === event.ctrlKey &&
               !!s.altKey === event.altKey &&
               !!s.shiftKey === event.shiftKey;
      });

      if (shortcut) {
        event.preventDefault();
        shortcut.action();
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [navigate]);

  return shortcuts;
};

// Hook to detect keyboard users for better focus management
export const useKeyboardUser = () => {
  useEffect(() => {
    let isKeyboardUser = false;

    const handleMouseDown = () => {
      isKeyboardUser = false;
      document.body.classList.remove('keyboard-user');
    };

    const handleTabKey = (event: KeyboardEvent) => {
      if (event.key === 'Tab') {
        isKeyboardUser = true;
        document.body.classList.add('keyboard-user');
      }
    };

    document.addEventListener('mousedown', handleMouseDown);
    document.addEventListener('keydown', handleTabKey);

    return () => {
      document.removeEventListener('mousedown', handleMouseDown);
      document.removeEventListener('keydown', handleTabKey);
    };
  }, []);
};
