import React from 'react';
import { NavLink, useLocation } from 'react-router-dom';
import { motion } from 'framer-motion';
import styles from './BottomNavigation.module.css';

const BottomNavigation: React.FC = () => {
  const location = useLocation();

  const navItems = [
    {
      path: '/',
      icon: '🏠',
      label: 'Home',
      ariaLabel: 'Navigate to home page'
    },
    {
      path: '/crypto-market',
      icon: '📈',
      label: 'Market',
      ariaLabel: 'Navigate to crypto market page'
    },
    {
      path: '/ai-tools',
      icon: '🤖',
      label: 'AI Tools',
      ariaLabel: 'Navigate to AI tools page'
    },
    {
      path: '/login',
      icon: '👤',
      label: 'Account',
      ariaLabel: 'Navigate to login page'
    }
  ];

  return (
    <nav className={styles.bottomNav} role="navigation" aria-label="Mobile navigation">
      <div className={styles.bottomNav__container}>
        {navItems.map((item) => {
          const isActive = location.pathname === item.path;
          
          return (
            <NavLink
              key={item.path}
              to={item.path}
              className={`${styles.bottomNav__item} ${isActive ? styles.active : ''}`}
              aria-label={item.ariaLabel}
              aria-current={isActive ? 'page' : undefined}
            >
              <motion.div
                className={styles.bottomNav__content}
                whileTap={{ scale: 0.95 }}
                animate={isActive ? { scale: 1.1 } : { scale: 1 }}
                transition={{ type: "spring", stiffness: 300, damping: 20 }}
              >
                <span className={styles.bottomNav__icon} aria-hidden="true">
                  {item.icon}
                </span>
                <span className={styles.bottomNav__label}>
                  {item.label}
                </span>
                {isActive && (
                  <motion.div
                    className={styles.bottomNav__indicator}
                    layoutId="activeIndicator"
                    initial={false}
                  />
                )}
              </motion.div>
            </NavLink>
          );
        })}
      </div>
    </nav>
  );
};

export default BottomNavigation;
