import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import SearchBox from '../SearchBox';
import MobileMenu from '../MobileMenu';
import InteractiveButton from '../InteractiveButton';
import styles from './Header.module.css';

const Header: React.FC = () => {
    const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
    const [isKeyboardUser, setIsKeyboardUser] = useState(false);
    const [isScrolled, setIsScrolled] = useState(false);

    useEffect(() => {
        // Track keyboard vs mouse usage for accessibility
        const handleKeydown = () => setIsKeyboardUser(true);
        const handleMousedown = () => setIsKeyboardUser(false);

        document.addEventListener('keydown', handleKeydown);
        document.addEventListener('mousedown', handleMousedown);

        // Apply class to body for focus styles
        document.body.classList.toggle('keyboard-user', isKeyboardUser);
        document.body.classList.toggle('mouse-user', !isKeyboardUser);

        return () => {
            document.removeEventListener('keydown', handleKeydown);
            document.removeEventListener('mousedown', handleMousedown);
        };
    }, [isKeyboardUser]);

    useEffect(() => {
        // Track scroll for header styling
        const handleScroll = () => {
            setIsScrolled(window.scrollY > 20);
        };

        window.addEventListener('scroll', handleScroll);
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    const toggleMobileMenu = () => {
        setIsMobileMenuOpen(!isMobileMenuOpen);
    };

    // Animation variants
    const headerVariants = {
        initial: { y: -100, opacity: 0 },
        animate: { 
            y: 0, 
            opacity: 1,
            transition: {
                duration: 0.6,
                ease: "easeOut" as const
            }
        }
    };

    const logoVariants = {
        initial: { scale: 0, rotate: -180 },
        animate: { 
            scale: 1, 
            rotate: 0,
            transition: {
                delay: 0.2,
                duration: 0.5,
                ease: "backOut" as const
            }
        },
        hover: {
            scale: 1.05,
            rotate: 5,
            transition: { duration: 0.2 }
        }
    };

    const navItemVariants = {
        initial: { opacity: 0, y: -20 },
        animate: (i: number) => ({
            opacity: 1,
            y: 0,
            transition: {
                delay: 0.4 + (i * 0.1),
                duration: 0.3
            }
        }),
        hover: {
            y: -2,
            transition: { duration: 0.2 }
        }
    };

    const navItems = [
        { label: 'Trade', href: '/' },
        { label: 'Markets', href: '/' },
        { label: 'Futures', href: '/' },
        { label: 'Earn', href: '/' },
        { label: 'AI Tools', href: '/ai-tools' }
    ];

    return (
        <>
            {/* Skip to main content for accessibility */}
            <a href="#main-content" className="skip-to-main">
                Skip to main content
            </a>
            
            <motion.header 
                className={`${styles.header} ${isScrolled ? styles.scrolled : ''}`} 
                role="banner"
                variants={headerVariants}
                initial="initial"
                animate="animate"
            >
                <div className={styles.container}>
                    <motion.div 
                        className={styles.logo}
                        variants={logoVariants}
                        whileHover="hover"
                    >
                        <Link to="/" className={styles.logoLink} aria-label="BlockCoinY homepage">
                            <motion.span 
                                className={styles.logoIcon} 
                                aria-hidden="true"
                                animate={{ rotate: [0, 10, -10, 0] }}
                                transition={{ duration: 2, repeat: Infinity, repeatDelay: 3 }}
                            >
                                💎
                            </motion.span>
                            BlockCoinY
                        </Link>
                    </motion.div>
                    
                    {/* Desktop Search */}
                    <motion.div 
                        className={styles.searchSection}
                        initial={{ opacity: 0, scale: 0.8 }}
                        animate={{ opacity: 1, scale: 1 }}
                        transition={{ delay: 0.6, duration: 0.4 }}
                    >
                        <SearchBox />
                    </motion.div>
                    
                    <nav className={styles.nav} role="navigation" aria-label="Main navigation">
                        <ul className={styles.navList}>
                            {navItems.map((item, index) => (
                                <motion.li 
                                    key={item.label}
                                    variants={navItemVariants}
                                    custom={index}
                                    whileHover="hover"
                                >
                                    <Link to={item.href} className={styles.navLink}>
                                        {item.label}
                                    </Link>
                                </motion.li>
                            ))}
                        </ul>
                    </nav>

                    <motion.div 
                        className={styles.rightSection}
                        initial={{ opacity: 0, x: 50 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ delay: 0.8, duration: 0.4 }}
                    >
                        {/* Desktop Auth Buttons */}
                        <div className={styles.authButtons}>
                            <InteractiveButton 
                                variant="outline" 
                                size="small"
                                ariaLabel="Get started with trading"
                            >
                                <Link to="/login" className={styles.loginBtn}>Get Started</Link>
                            </InteractiveButton>
                            <InteractiveButton 
                                variant="primary" 
                                size="small"
                                ariaLabel="Sign up for new account"
                            >
                                <Link to="/signup" className={styles.signupBtn}>Sign Up</Link>
                            </InteractiveButton>
                        </div>

                        {/* Mobile Menu Button */}
                        <div className={styles.mobileMenuWrapper}>
                            <motion.button
                                className={styles.mobileMenuButton}
                                onClick={toggleMobileMenu}
                                aria-label={isMobileMenuOpen ? 'Close menu' : 'Open menu'}
                                aria-expanded={isMobileMenuOpen}
                                type="button"
                                whileTap={{ scale: 0.95 }}
                                whileHover={{ scale: 1.05 }}
                            >
                                <AnimatePresence mode="wait">
                                    <motion.span 
                                        key={isMobileMenuOpen ? 'close' : 'open'}
                                        className={`${styles.hamburger} ${isMobileMenuOpen ? styles.open : ''}`}
                                        initial={{ rotate: 0 }}
                                        animate={{ rotate: isMobileMenuOpen ? 180 : 0 }}
                                        transition={{ duration: 0.3 }}
                                    >
                                        <span></span>
                                        <span></span>
                                        <span></span>
                                    </motion.span>
                                </AnimatePresence>
                            </motion.button>
                        </div>
                    </motion.div>
                </div>
            </motion.header>

            {/* Mobile Menu */}
            <MobileMenu 
                isOpen={isMobileMenuOpen} 
                onClose={() => setIsMobileMenuOpen(false)} 
            />
        </>
    );
};

export default Header;
