import React, { Suspense } from 'react';
import { createBrowserRouter, RouterProvider, Outlet } from 'react-router-dom';
import MainLayout from './components/layout/MainLayout';
import ScrollToTop from './components/layout/ScrollToTop';
import PageTransition from './components/common/PageTransition';
import ErrorBoundary from './components/common/ErrorBoundary';
import SkeletonLoader from './components/common/SkeletonLoader';
import { ToastProvider } from './components/common/Toast';
import { useKeyboardUser } from './hooks/useKeyboardShortcuts';
import './App.css';
import './styles/accessibility.css';

// Lazy load pages for better performance
const Home = React.lazy(() => import('./pages/Home'));
const AITools = React.lazy(() => import('./pages/AITools'));
const CryptoMarketPage = React.lazy(() => import('./pages/CryptoMarketPage'));
const Login = React.lazy(() => import('./pages/Login'));
const SignUp = React.lazy(() => import('./pages/SignUp'));
const NotFound = React.lazy(() => import('./pages/NotFound'));

// Root layout component that includes ScrollToTop
const RootLayout: React.FC = () => {
  useKeyboardUser();
  
  return (
    <>
      <ScrollToTop />
      <Outlet />
    </>
  );
};

const router = createBrowserRouter([
  {
    path: '/',
    element: <RootLayout />,
    children: [
      {
        index: true,
        element: (
          <MainLayout>
            <Suspense fallback={<div style={{ padding: '40px' }}><SkeletonLoader variant="card" height="400px" /></div>}>
              <PageTransition>
                <Home />
              </PageTransition>
            </Suspense>
          </MainLayout>
        ),
      },
      {
        path: 'ai-tools',
        element: (
          <MainLayout>
            <Suspense fallback={<div style={{ padding: '40px' }}><SkeletonLoader variant="card" height="400px" /></div>}>
              <PageTransition>
                <AITools />
              </PageTransition>
            </Suspense>
          </MainLayout>
        ),
      },
      {
        path: 'crypto-market',
        element: (
          <MainLayout>
            <Suspense fallback={<div style={{ padding: '40px' }}><SkeletonLoader variant="card" height="400px" /></div>}>
              <PageTransition>
                <CryptoMarketPage />
              </PageTransition>
            </Suspense>
          </MainLayout>
        ),
      },
      {
        path: 'login',
        element: (
          <Suspense fallback={<div style={{ padding: '40px' }}><SkeletonLoader variant="card" height="400px" /></div>}>
            <Login />
          </Suspense>
        ),
      },
      {
        path: 'signup',
        element: (
          <Suspense fallback={<div style={{ padding: '40px' }}><SkeletonLoader variant="card" height="400px" /></div>}>
            <SignUp />
          </Suspense>
        ),
      },
      {
        path: '*',
        element: (
          <MainLayout>
            <Suspense fallback={<div style={{ padding: '40px' }}><SkeletonLoader variant="card" height="400px" /></div>}>
              <NotFound />
            </Suspense>
          </MainLayout>
        ),
      },
    ],
  },
], {
  basename: process.env.NODE_ENV === 'production' ? '/BlockCoinY' : '',
});

const App: React.FC = () => {
  return (
    <ErrorBoundary>
      <ToastProvider>
        <RouterProvider router={router} />
      </ToastProvider>
    </ErrorBoundary>
  );
};

export default App;
